#!/usr/bin/env python3
# -*- coding: utf-8 -*-

"""Fill an HWPX (zip) template with JSON values.

This script:
- Extracts the template HWPX
- Replaces {{placeholders}} in section XML files with JSON values
- Normalizes budget fields (remove commas in numeric portion while keeping currency symbol)
- Appends month-span '(N개월)' to phase lines (1단계/2단계/3단계) based on date ranges in text
- Removes stale layout cache elements (linesegarray / any tag containing 'lineseg') from paragraphs whose text changed
- Repackages the result as /root/project_proposal_ready.hwpx

Designed to preserve namespaces/prefixes using xml.etree.ElementTree.
"""

from __future__ import annotations

import json
import os
import re
import sys
import zipfile
from dataclasses import dataclass
from typing import Dict, List, Optional, Tuple
import xml.etree.ElementTree as ET


TEMPLATE_HWPX = "/root/project_proposal_template.hwpx"
INPUT_JSON = "/root/project_proposal.json"
WORKDIR = "/tmp/hwpx_work"
EXTRACT_DIR = os.path.join(WORKDIR, "template_contents")
OUTPUT_HWPX = "/root/project_proposal_ready.hwpx"


HP_NS = "http://www.hancom.co.kr/hwpml/2010/HWPML"
NS = {"hp": HP_NS}
ET.register_namespace("hp", HP_NS)


PLACEHOLDER_RE = re.compile(r"\{\{\s*([^{}\s]+)\s*\}\}")


def load_json_mapping(path: str) -> Dict[str, str]:
    with open(path, "r", encoding="utf-8") as f:
        data = json.load(f)

    # Convert values to strings (HWPX text nodes are strings).
    mapping: Dict[str, str] = {}
    for k, v in data.items():
        if v is None:
            mapping[str(k)] = ""
        elif isinstance(v, (int, float)):
            mapping[str(k)] = str(v)
        else:
            mapping[str(k)] = str(v)

    mapping = normalize_budget_fields(mapping)
    return mapping


def normalize_budget_fields(mapping: Dict[str, str]) -> Dict[str, str]:
    """Normalize currency strings for budget/cost keys.

    Requirement: remove commas from numeric part while keeping leading currency symbol.
    Example: ₩1,000,000 -> ₩1000000
    """

    def looks_like_currency_amount(s: str) -> bool:
        # Any digits with comma separators, optionally preceded by a currency symbol.
        return bool(re.search(r"\d{1,3}(,\d{3})+", s))

    def normalize_currency_commas(s: str) -> str:
        # Keep any leading non-digit prefix (currency symbol, label), remove commas in digit chunks.
        # E.g. '₩450,000,000' -> '₩450000000'
        m = re.match(r"^(\D*)([\d,]+)(.*)$", s)
        if not m:
            return s
        prefix, num, suffix = m.group(1), m.group(2), m.group(3)
        return f"{prefix}{num.replace(',', '')}{suffix}"

    budgetish_key_re = re.compile(r"(예산|비용|경비|budget|cost)", re.IGNORECASE)

    out: Dict[str, str] = dict(mapping)
    for k, v in mapping.items():
        if not isinstance(v, str):
            continue
        if not budgetish_key_re.search(k):
            continue
        if looks_like_currency_amount(v):
            out[k] = normalize_currency_commas(v)
    return out


def replace_placeholders_in_text(text: str, mapping: Dict[str, str]) -> Tuple[str, bool]:
    changed = False

    def repl(m: re.Match) -> str:
        nonlocal changed
        key = m.group(1)
        if key in mapping:
            changed = True
            return mapping[key]
        # Unknown placeholder: leave as-is (but verification later will fail if any remain).
        return m.group(0)

    new_text = PLACEHOLDER_RE.sub(repl, text)
    return new_text, changed


def extract_year_months(text: str) -> List[Tuple[int, int]]:
    """Extract year-month pairs in order of appearance.

    Supports patterns like:
    - 2026-08
    - 2026.08
    - 2026-08-01 (month is still captured)
    - 2026.08.01
    """
    pairs: List[Tuple[int, int]] = []
    for m in re.finditer(r"(\d{4})[.\-](\d{2})", text):
        y = int(m.group(1))
        mo = int(m.group(2))
        if 1 <= mo <= 12:
            pairs.append((y, mo))
    return pairs


def month_span_inclusive(start: Tuple[int, int], end: Tuple[int, int]) -> int:
    sy, sm = start
    ey, em = end
    return (ey - sy) * 12 + (em - sm) + 1


def append_phase_month_span(text: str) -> Tuple[str, bool]:
    """Append '(N개월)' to phase lines for 1단계/2단계/3단계.

    We detect phase lines by presence of '1단계', '2단계', '3단계'.
    Month span is derived from date ranges present in the line.
    """
    if "개월" in text:
        return text, False

    if not any(tok in text for tok in ("1단계", "2단계", "3단계")):
        return text, False

    pairs = extract_year_months(text)
    if len(pairs) >= 2:
        months = month_span_inclusive(pairs[0], pairs[1])
    elif len(pairs) == 1:
        months = 1
    else:
        return text, False

    new_text = text.rstrip() + f" ({months}개월)"
    return new_text, True


def localname(tag: str) -> str:
    if tag.startswith("{") and "}" in tag:
        return tag.split("}", 1)[1]
    return tag


def remove_lineseg_elements(elem: ET.Element) -> int:
    """Remove descendant elements whose tag localname contains 'lineseg' (case-insensitive)."""
    removed = 0

    def recurse(parent: ET.Element):
        nonlocal removed
        # Iterate over a static list since we may modify children.
        for child in list(parent):
            lname = localname(child.tag).lower()
            if "lineseg" in lname:
                parent.remove(child)
                removed += 1
                continue
            recurse(child)

    recurse(elem)
    return removed


def paragraph_text_nodes(p: ET.Element) -> List[ET.Element]:
    # All hp:t descendants within the paragraph.
    return list(p.findall(".//hp:t", NS))


def paragraph_full_text(ts: List[ET.Element]) -> str:
    return "".join((t.text or "") for t in ts)


@dataclass
class ChangeRecord:
    file_path: str
    paragraphs_changed: int
    lineseg_removed: int


def process_section_xml(xml_path: str, mapping: Dict[str, str]) -> ChangeRecord:
    tree = ET.parse(xml_path)
    root = tree.getroot()

    paragraphs_changed = 0
    lineseg_removed_total = 0

    for p in root.findall(".//hp:p", NS):
        ts = paragraph_text_nodes(p)
        if not ts:
            continue

        changed_here = False

        # Pass 1: replace placeholders per text node.
        for t in ts:
            old = t.text or ""
            new, ch = replace_placeholders_in_text(old, mapping)
            if ch and new != old:
                t.text = new
                changed_here = True

        # Pass 2: if placeholders still remain across boundaries, collapse.
        full = paragraph_full_text(ts)
        if "{{" in full and "}}" in full:
            replaced, ch = replace_placeholders_in_text(full, mapping)
            if ch and replaced != full:
                ts[0].text = replaced
                for t in ts[1:]:
                    t.text = ""
                changed_here = True
            full = replaced

        # Phase month-span append (operates on full paragraph text).
        # Only attempt if we have at least one text node.
        full_now = paragraph_full_text(ts)
        appended, ch = append_phase_month_span(full_now)
        if ch and appended != full_now:
            ts[0].text = appended
            for t in ts[1:]:
                t.text = ""
            changed_here = True

        if changed_here:
            paragraphs_changed += 1
            # Remove layout cache elements from modified paragraphs.
            lineseg_removed_total += remove_lineseg_elements(p)

    out_bytes = ET.tostring(root, encoding="utf-8", xml_declaration=True)
    if b"{{" in out_bytes or b"}}" in out_bytes:
        raise RuntimeError(f"Placeholders remain after processing: {xml_path}")

    with open(xml_path, "wb") as f:
        f.write(out_bytes)

    return ChangeRecord(
        file_path=xml_path,
        paragraphs_changed=paragraphs_changed,
        lineseg_removed=lineseg_removed_total,
    )


def extract_template() -> List[zipfile.ZipInfo]:
    # Return original zip infos (for ordering/compression matching).
    with zipfile.ZipFile(TEMPLATE_HWPX, "r") as z:
        infos = z.infolist()
        z.extractall(EXTRACT_DIR)
        return infos


def repack_hwpx(original_infos: List[zipfile.ZipInfo]) -> None:
    # Map original compression settings by filename.
    comp_by_name = {zi.filename: zi.compress_type for zi in original_infos}
    orig_order = [zi.filename for zi in original_infos]

    # Gather extracted files.
    extracted_files: List[str] = []
    for root, _, files in os.walk(EXTRACT_DIR):
        for fn in files:
            extracted_files.append(os.path.join(root, fn))

    # Build arcname mapping.
    arc_by_path: Dict[str, str] = {}
    for fp in extracted_files:
        arcname = os.path.relpath(fp, EXTRACT_DIR).replace(os.sep, "/")
        arc_by_path[fp] = arcname

    # Order files: follow original order first, then any extras.
    ordered_arcnames: List[str] = []
    existing_arcnames = set(arc_by_path.values())
    for name in orig_order:
        if name in existing_arcnames:
            ordered_arcnames.append(name)
    for name in sorted(existing_arcnames):
        if name not in ordered_arcnames:
            ordered_arcnames.append(name)

    # Reverse mapping arcname -> filesystem path
    path_by_arc = {arc: fp for fp, arc in arc_by_path.items()}

    # Create zip.
    with zipfile.ZipFile(OUTPUT_HWPX, "w") as out_z:
        # If mimetype exists, store it first and uncompressed.
        if "mimetype" in path_by_arc:
            fp = path_by_arc["mimetype"]
            zi = zipfile.ZipInfo("mimetype")
            zi.compress_type = zipfile.ZIP_STORED
            with open(fp, "rb") as f:
                out_z.writestr(zi, f.read())

        for arcname in ordered_arcnames:
            if arcname == "mimetype":
                continue
            fp = path_by_arc[arcname]
            compress_type = comp_by_name.get(arcname, zipfile.ZIP_DEFLATED)

            # Use writestr with ZipInfo to set compression type explicitly.
            zi = zipfile.ZipInfo(arcname)
            zi.compress_type = compress_type
            # Preserve a reasonable file mode (readable), but don't rely on original external_attr.
            zi.external_attr = (0o644 & 0xFFFF) << 16
            with open(fp, "rb") as f:
                out_z.writestr(zi, f.read())


def main() -> int:
    mapping = load_json_mapping(INPUT_JSON)

    # Step: extract template
    if os.path.exists(EXTRACT_DIR):
        # Clean existing extraction to avoid stale files.
        for root, dirs, files in os.walk(EXTRACT_DIR, topdown=False):
            for fn in files:
                os.remove(os.path.join(root, fn))
            for dn in dirs:
                os.rmdir(os.path.join(root, dn))
    os.makedirs(EXTRACT_DIR, exist_ok=True)

    original_infos = extract_template()

    # Find XML files containing placeholders.
    xml_files: List[str] = []
    for root, _, files in os.walk(EXTRACT_DIR):
        for fn in files:
            if not fn.lower().endswith(".xml"):
                continue
            fp = os.path.join(root, fn)
            try:
                with open(fp, "rb") as f:
                    if b"{{" in f.read():
                        xml_files.append(fp)
            except OSError:
                continue

    if not xml_files:
        raise RuntimeError("No XML files with placeholders found")

    # Process each.
    records: List[ChangeRecord] = []
    for fp in sorted(xml_files):
        records.append(process_section_xml(fp, mapping))

    # Sanity: expected phase spans (benchmark). We compute from the actual text we wrote.
    # This is only a check; it does not modify anything.
    expected = {"1단계": 3, "2단계": 3, "3단계": 1}
    found: Dict[str, int] = {}
    for fp in sorted(xml_files):
        with open(fp, "r", encoding="utf-8") as f:
            content = f.read()
        for phase, exp in expected.items():
            if phase in content:
                m = re.search(re.escape(phase) + r"[^\n]*\((\d+)개월\)", content)
                if m:
                    found[phase] = int(m.group(1))
    missing = [k for k in expected if k not in found]
    if missing:
        raise RuntimeError(f"Missing month-span annotations for phases: {missing}")
    mismatched = {k: (found[k], expected[k]) for k in expected if found.get(k) != expected[k]}
    if mismatched:
        raise RuntimeError(f"Month-span annotations do not match benchmark: {mismatched}")

    # Repack.
    repack_hwpx(original_infos)

    # Final check: ensure output is a readable zip.
    with zipfile.ZipFile(OUTPUT_HWPX, "r") as z:
        bad = z.testzip()
        if bad is not None:
            raise RuntimeError(f"Output zip failed integrity check at member: {bad}")

    # Emit a short summary to stdout for debugging.
    print("Wrote:", OUTPUT_HWPX)
    for r in records:
        print(f"Processed {r.file_path}: paragraphs_changed={r.paragraphs_changed}, lineseg_removed={r.lineseg_removed}")

    return 0


if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except Exception as e:
        print("ERROR:", e, file=sys.stderr)
        raise

